package com.yupi.template.storage;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.io.*;import java.util.zip.*;import com.yupi.template.controller.ArticleImageController;import com.yupi.template.service.*;import com.yupi.template.model.entity.User;import com.yupi.template.model.vo.ArticleVO;import org.springframework.beans.factory.ObjectProvider;import org.springframework.jdbc.core.JdbcTemplate;import jakarta.servlet.http.HttpServletRequest;
class MarkdownExportTest {
 @TempDir Path root;
 @Test void standaloneContainsActualImageBytesAndZipKeepsInlinePosition()throws Exception{var store=new LocalImageStorage(root.toString(),10000);String url=store.save(com.yupi.template.model.dto.image.ImageData.fromBytes(A4StorageTest.png(),"image/png"),"x");var users=mock(UserService.class);var articles=mock(ArticleService.class);var req=mock(HttpServletRequest.class);var user=new User();when(users.getLoginUser(req)).thenReturn(user);var a=new ArticleVO();a.setMainTitle("title");a.setSubTitle("subtitle");a.setFullContent("BEFORE\n\n![图片]("+url+")\n\nAFTER");var i=new ArticleVO.ImageItem();i.setUrl(url);a.setImages(List.of(i));when(articles.getArticleDetail("task",user)).thenReturn(a);ObjectProvider<LocalImageStorage> provider=mock(ObjectProvider.class);when(provider.getIfAvailable()).thenReturn(store);var c=new ArticleImageController(provider,users,articles,mock(JdbcTemplate.class));String md=new String(c.markdownExport("task",req).getBody(),StandardCharsets.UTF_8);assertFalse(md.contains("/api/images/"));var match=java.util.regex.Pattern.compile("data:image/png;base64,([A-Za-z0-9+/=]+)").matcher(md);assertTrue(match.find());assertArrayEquals(store.read(url.substring(12)),Base64.getDecoder().decode(match.group(1)));assertTrue(md.indexOf("BEFORE")<md.indexOf("data:image"));assertTrue(md.indexOf("data:image")<md.indexOf("AFTER"));var files=new HashMap<String,byte[]>();try(var z=new ZipInputStream(new ByteArrayInputStream(c.export("task",req).getBody()))){for(ZipEntry e;(e=z.getNextEntry())!=null;)files.put(e.getName(),z.readAllBytes());}String html=new String(files.get("index.html"),StandardCharsets.UTF_8);assertTrue(html.indexOf("BEFORE")<html.indexOf("<img"));assertTrue(html.indexOf("<img")<html.indexOf("AFTER"));assertNotNull(files.get("images/"+url.substring(12)+".png"));assertTrue(new String(files.get("article.md"),StandardCharsets.UTF_8).contains("images/"));}
 @Test void markdownRequiresLogin(){var users=mock(UserService.class);when(users.getLoginUser(any())).thenThrow(new com.yupi.template.exception.BusinessException(com.yupi.template.exception.ErrorCode.NOT_LOGIN_ERROR));ObjectProvider<LocalImageStorage> provider=mock(ObjectProvider.class);assertThrows(com.yupi.template.exception.BusinessException.class,()->new ArticleImageController(provider,users,mock(ArticleService.class),mock(JdbcTemplate.class)).markdownExport("t",mock(HttpServletRequest.class)));verifyNoInteractions(provider);}
 @Test void unmatchedLocalReferenceIsNotReadFromDisk(){var users=mock(UserService.class);var articles=mock(ArticleService.class);var a=new ArticleVO();a.setFullContent("![x](/api/images/"+"a".repeat(32)+")");when(articles.getArticleDetail(anyString(),any())).thenReturn(a);ObjectProvider<LocalImageStorage> provider=mock(ObjectProvider.class);assertThrows(com.yupi.template.exception.BusinessException.class,()->new ArticleImageController(provider,users,articles,mock(JdbcTemplate.class)).markdownExport("t",mock(HttpServletRequest.class)));verifyNoInteractions(provider);}
}
